        ref float input2 = ref MemoryMarshal.GetReference(row2);
        ref float input3 = ref MemoryMarshal.GetReference(row3);
        ref float input4 = ref MemoryMarshal.GetReference(row4);
        ref float min = ref MemoryMarshal.GetReference(minimum);
        ref float max = ref MemoryMarshal.GetReference(maximum);

        for (int y = 0; y < 8; y++)
        {
            ref float output = ref destination[y * stride];
            KernelOperator phase0 = new(kernels.Slice(((y * 8) + 0) * KernelLength, KernelLength));
            KernelOperator phase1 = new(kernels.Slice(((y * 8) + 1) * KernelLength, KernelLength));
            KernelOperator phase2 = new(kernels.Slice(((y * 8) + 2) * KernelLength, KernelLength));
            KernelOperator phase3 = new(kernels.Slice(((y * 8) + 3) * KernelLength, KernelLength));
            KernelOperator phase4 = new(kernels.Slice(((y * 8) + 4) * KernelLength, KernelLength));
            KernelOperator phase5 = new(kernels.Slice(((y * 8) + 5) * KernelLength, KernelLength));
            KernelOperator phase6 = new(kernels.Slice(((y * 8) + 6) * KernelLength, KernelLength));
            KernelOperator phase7 = new(kernels.Slice(((y * 8) + 7) * KernelLength, KernelLength));
            int x = 0;

            // Each lane reconstructs one input center. Every phase reads the same complete five-by-five neighborhood.
            // Interleaving writes phase0,phase1,... for center0, then the same phase order for each following center.
            if (Vector512.IsHardwareAccelerated)
            {
                for (; x <= minimum.Length - Vector512<float>.Count; x += Vector512<float>.Count)
                {
                    Vector512<float> lower = Vector512.LoadUnsafe(ref min, (uint)x);
                    Vector512<float> upper = Vector512.LoadUnsafe(ref max, (uint)x);
                    Vector512<float> result0 = phase0.Invoke512(ref input0, ref input1, ref input2, ref input3, ref input4, x);
                    result0 = Vector512.Min(Vector512.Max(result0, lower), upper);
                    Vector512<float> result1 = phase1.Invoke512(ref input0, ref input1, ref input2, ref input3, ref input4, x);
                    result1 = Vector512.Min(Vector512.Max(result1, lower), upper);
                    Vector512<float> result2 = phase2.Invoke512(ref input0, ref input1, ref input2, ref input3, ref input4, x);
                    result2 = Vector512.Min(Vector512.Max(result2, lower), upper);
                    Vector512<float> result3 = phase3.Invoke512(ref input0, ref input1, ref input2, ref input3, ref input4, x);
                    result3 = Vector512.Min(Vector512.Max(result3, lower), upper);
                    Vector512<float> result4 = phase4.Invoke512(ref input0, ref input1, ref input2, ref input3, ref input4, x);
                    result4 = Vector512.Min(Vector512.Max(result4, lower), upper);
                    Vector512<float> result5 = phase5.Invoke512(ref input0, ref input1, ref input2, ref input3, ref input4, x);
                    result5 = Vector512.Min(Vector512.Max(result5, lower), upper);
                    Vector512<float> result6 = phase6.Invoke512(ref input0, ref input1, ref input2, ref input3, ref input4, x);
                    result6 = Vector512.Min(Vector512.Max(result6, lower), upper);
                    Vector512<float> result7 = phase7.Invoke512(ref input0, ref input1, ref input2, ref input3, ref input4, x);
                    result7 = Vector512.Min(Vector512.Max(result7, lower), upper);
                    SimdUtils.Interleave8(result0, result1, result2, result3, result4, result5, result6, result7, ref Unsafe.Add(ref output, x * 8));
                }
            }

            if (Vector256.IsHardwareAccelerated)
            {
                for (; x <= minimum.Length - Vector256<float>.Count; x += Vector256<float>.Count)
                {
                    Vector256<float> lower = Vector256.LoadUnsafe(ref min, (uint)x);
                    Vector256<float> upper = Vector256.LoadUnsafe(ref max, (uint)x);
                    Vector256<float> result0 = phase0.Invoke256(ref input0, ref input1, ref input2, ref input3, ref input4, x);
                    result0 = Vector256.Min(Vector256.Max(result0, lower), upper);
                    Vector256<float> result1 = phase1.Invoke256(ref input0, ref input1, ref input2, ref input3, ref input4, x);
                    result1 = Vector256.Min(Vector256.Max(result1, lower), upper);
                    Vector256<float> result2 = phase2.Invoke256(ref input0, ref input1, ref input2, ref input3, ref input4, x);
                    result2 = Vector256.Min(Vector256.Max(result2, lower), upper);
                    Vector256<float> result3 = phase3.Invoke256(ref input0, ref input1, ref input2, ref input3, ref input4, x);
                    result3 = Vector256.Min(Vector256.Max(result3, lower), upper);
                    Vector256<float> result4 = phase4.Invoke256(ref input0, ref input1, ref input2, ref input3, ref input4, x);
                    result4 = Vector256.Min(Vector256.Max(result4, lower), upper);
                    Vector256<float> result5 = phase5.Invoke256(ref input0, ref input1, ref input2, ref input3, ref input4, x);
                    result5 = Vector256.Min(Vector256.Max(result5, lower), upper);
                    Vector256<float> result6 = phase6.Invoke256(ref input0, ref input1, ref input2, ref input3, ref input4, x);
                    result6 = Vector256.Min(Vector256.Max(result6, lower), upper);
                    Vector256<float> result7 = phase7.Invoke256(ref input0, ref input1, ref input2, ref input3, ref input4, x);
                    result7 = Vector256.Min(Vector256.Max(result7, lower), upper);
                    SimdUtils.Interleave8(result0, result1, result2, result3, result4, result5, result6, result7, ref Unsafe.Add(ref output, x * 8));
                }
            }

            if (Vector128.IsHardwareAccelerated)
            {
                for (; x <= minimum.Length - Vector128<float>.Count; x += Vector128<float>.Count)
                {
                    Vector128<float> lower = Vector128.LoadUnsafe(ref min, (uint)x);
                    Vector128<float> upper = Vector128.LoadUnsafe(ref max, (uint)x);
                    Vector128<float> result0 = phase0.Invoke128(ref input0, ref input1, ref input2, ref input3, ref input4, x);
                    result0 = Vector128.Min(Vector128.Max(result0, lower), upper);
                    Vector128<float> result1 = phase1.Invoke128(ref input0, ref input1, ref input2, ref input3, ref input4, x);
                    result1 = Vector128.Min(Vector128.Max(result1, lower), upper);
                    Vector128<float> result2 = phase2.Invoke128(ref input0, ref input1, ref input2, ref input3, ref input4, x);
                    result2 = Vector128.Min(Vector128.Max(result2, lower), upper);
                    Vector128<float> result3 = phase3.Invoke128(ref input0, ref input1, ref input2, ref input3, ref input4, x);
                    result3 = Vector128.Min(Vector128.Max(result3, lower), upper);
                    Vector128<float> result4 = phase4.Invoke128(ref input0, ref input1, ref input2, ref input3, ref input4, x);
                    result4 = Vector128.Min(Vector128.Max(result4, lower), upper);
                    Vector128<float> result5 = phase5.Invoke128(ref input0, ref input1, ref input2, ref input3, ref input4, x);
                    result5 = Vector128.Min(Vector128.Max(result5, lower), upper);
                    Vector128<float> result6 = phase6.Invoke128(ref input0, ref input1, ref input2, ref input3, ref input4, x);
                    result6 = Vector128.Min(Vector128.Max(result6, lower), upper);
                    Vector128<float> result7 = phase7.Invoke128(ref input0, ref input1, ref input2, ref input3, ref input4, x);
                    result7 = Vector128.Min(Vector128.Max(result7, lower), upper);
                    SimdUtils.Interleave8(result0, result1, result2, result3, result4, result5, result6, result7, ref Unsafe.Add(ref output, x * 8));
                }
            }

            for (; x < minimum.Length; x++)
            {
                float lower = Unsafe.Add(ref min, x);
                float upper = Unsafe.Add(ref max, x);
                float result0 = phase0.InvokeScalar(ref input0, ref input1, ref input2, ref input3, ref input4, x);
                Unsafe.Add(ref output, (x * 8) + 0) = MathF.Min(MathF.Max(result0, lower), upper);
                float result1 = phase1.InvokeScalar(ref input0, ref input1, ref input2, ref input3, ref input4, x);
                Unsafe.Add(ref output, (x * 8) + 1) = MathF.Min(MathF.Max(result1, lower), upper);
                float result2 = phase2.InvokeScalar(ref input0, ref input1, ref input2, ref input3, ref input4, x);
                Unsafe.Add(ref output, (x * 8) + 2) = MathF.Min(MathF.Max(result2, lower), upper);
                float result3 = phase3.InvokeScalar(ref input0, ref input1, ref input2, ref input3, ref input4, x);
                Unsafe.Add(ref output, (x * 8) + 3) = MathF.Min(MathF.Max(result3, lower), upper);
                float result4 = phase4.InvokeScalar(ref input0, ref input1, ref input2, ref input3, ref input4, x);
                Unsafe.Add(ref output, (x * 8) + 4) = MathF.Min(MathF.Max(result4, lower), upper);
                float result5 = phase5.InvokeScalar(ref input0, ref input1, ref input2, ref input3, ref input4, x);
                Unsafe.Add(ref output, (x * 8) + 5) = MathF.Min(MathF.Max(result5, lower), upper);
                float result6 = phase6.InvokeScalar(ref input0, ref input1, ref input2, ref input3, ref input4, x);
                Unsafe.Add(ref output, (x * 8) + 6) = MathF.Min(MathF.Max(result6, lower), upper);
                float result7 = phase7.InvokeScalar(ref input0, ref input1, ref input2, ref input3, ref input4, x);
                Unsafe.Add(ref output, (x * 8) + 7) = MathF.Min(MathF.Max(result7, lower), upper);
            }
        }
    }

    /// <summary>
    /// Evaluates one borrowed phase kernel with three independent accumulation chains.
    /// </summary>
    /// <remarks>
    /// The borrowed coefficients remain valid during one chunk. This operation stores no input samples and allocates no memory.
    /// </remarks>
    private readonly ref struct KernelOperator
    {
        /// <summary>
        /// The twenty-five row-major coefficients borrowed from the upsampler's prepared allocation.
        /// </summary>
        private readonly ReadOnlySpan<float> weights;

        /// <summary>
        /// Binds one prepared phase without copying coefficients.
        /// </summary>
        /// <param name="weights">Exactly twenty-five row-major coefficients.</param>
        public KernelOperator(ReadOnlySpan<float> weights) => this.weights = weights;

        /// <summary>
        /// Applies the native three-chain stencil to Vector512<float>.Count independent input centers.
        /// </summary>
        /// <param name="row0">The first input row, including horizontal halos.</param>
        /// <param name="row1">The second input row.</param>
        /// <param name="row2">The middle input row.</param>
        /// <param name="row3">The fourth input row.</param>
        /// <param name="row4">The fifth input row.</param>
        /// <param name="x">The first center's offset before applying the two-sample left halo.</param>
        /// <returns>The unbounded weighted sum. The caller applies the neighborhood anti-ringing bounds.</returns>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public Vector512<float> Invoke512(ref float row0, ref float row1, ref float row2, ref float row3, ref float row4, int x)
        {
            Vector512<float> acc0 = Vector512.LoadUnsafe(ref row0, (uint)(x + 0)) * Vector512.Create(this.weights[0]);
            Vector512<float> acc1 = Vector512.LoadUnsafe(ref row0, (uint)(x + 1)) * Vector512.Create(this.weights[1]);
            Vector512<float> acc2 = Vector512.LoadUnsafe(ref row0, (uint)(x + 2)) * Vector512.Create(this.weights[2]);
            acc0 = Vector512.MultiplyAddEstimate(Vector512.LoadUnsafe(ref row0, (uint)(x + 3)), Vector512.Create(this.weights[3]), acc0);
            acc1 = Vector512.MultiplyAddEstimate(Vector512.LoadUnsafe(ref row0, (uint)(x + 4)), Vector512.Create(this.weights[4]), acc1);
            acc2 = Vector512.MultiplyAddEstimate(Vector512.LoadUnsafe(ref row1, (uint)(x + 0)), Vector512.Create(this.weights[5]), acc2);
            acc0 = Vector512.MultiplyAddEstimate(Vector512.LoadUnsafe(ref row1, (uint)(x + 1)), Vector512.Create(this.weights[6]), acc0);
            acc1 = Vector512.MultiplyAddEstimate(Vector512.LoadUnsafe(ref row1, (uint)(x + 2)), Vector512.Create(this.weights[7]), acc1);
            acc2 = Vector512.MultiplyAddEstimate(Vector512.LoadUnsafe(ref row1, (uint)(x + 3)), Vector512.Create(this.weights[8]), acc2);
            acc0 = Vector512.MultiplyAddEstimate(Vector512.LoadUnsafe(ref row1, (uint)(x + 4)), Vector512.Create(this.weights[9]), acc0);
            acc1 = Vector512.MultiplyAddEstimate(Vector512.LoadUnsafe(ref row2, (uint)(x + 0)), Vector512.Create(this.weights[10]), acc1);
            acc2 = Vector512.MultiplyAddEstimate(Vector512.LoadUnsafe(ref row2, (uint)(x + 1)), Vector512.Create(this.weights[11]), acc2);
            acc0 = Vector512.MultiplyAddEstimate(Vector512.LoadUnsafe(ref row2, (uint)(x + 2)), Vector512.Create(this.weights[12]), acc0);
            acc1 = Vector512.MultiplyAddEstimate(Vector512.LoadUnsafe(ref row2, (uint)(x + 3)), Vector512.Create(this.weights[13]), acc1);
            acc2 = Vector512.MultiplyAddEstimate(Vector512.LoadUnsafe(ref row2, (uint)(x + 4)), Vector512.Create(this.weights[14]), acc2);
            acc0 = Vector512.MultiplyAddEstimate(Vector512.LoadUnsafe(ref row3, (uint)(x + 0)), Vector512.Create(this.weights[15]), acc0);
            acc1 = Vector512.MultiplyAddEstimate(Vector512.LoadUnsafe(ref row3, (uint)(x + 1)), Vector512.Create(this.weights[16]), acc1);
            acc2 = Vector512.MultiplyAddEstimate(Vector512.LoadUnsafe(ref row3, (uint)(x + 2)), Vector512.Create(this.weights[17]), acc2);
            acc0 = Vector512.MultiplyAddEstimate(Vector512.LoadUnsafe(ref row3, (uint)(x + 3)), Vector512.Create(this.weights[18]), acc0);
            acc1 = Vector512.MultiplyAddEstimate(Vector512.LoadUnsafe(ref row3, (uint)(x + 4)), Vector512.Create(this.weights[19]), acc1);
            acc2 = Vector512.MultiplyAddEstimate(Vector512.LoadUnsafe(ref row4, (uint)(x + 0)), Vector512.Create(this.weights[20]), acc2);
            acc0 = Vector512.MultiplyAddEstimate(Vector512.LoadUnsafe(ref row4, (uint)(x + 1)), Vector512.Create(this.weights[21]), acc0);
            acc1 = Vector512.MultiplyAddEstimate(Vector512.LoadUnsafe(ref row4, (uint)(x + 2)), Vector512.Create(this.weights[22]), acc1);
            acc2 = Vector512.MultiplyAddEstimate(Vector512.LoadUnsafe(ref row4, (uint)(x + 3)), Vector512.Create(this.weights[23]), acc2);
            acc0 = Vector512.MultiplyAddEstimate(Vector512.LoadUnsafe(ref row4, (uint)(x + 4)), Vector512.Create(this.weights[24]), acc0);

            // Native adds chains one and two first, then chain zero. Regrouping this sum changes cancellation and rounding.
            return (acc1 + acc2) + acc0;
        }

        /// <summary>
        /// Applies the native three-chain stencil to Vector256<float>.Count independent input centers.
        /// </summary>
        /// <param name="row0">The first input row, including horizontal halos.</param>
