            Vector256<float> acc1 = Vector256.LoadUnsafe(ref row0, (uint)(x + 1)) * Vector256.Create(this.weights[1]);
            Vector256<float> acc2 = Vector256.LoadUnsafe(ref row0, (uint)(x + 2)) * Vector256.Create(this.weights[2]);
            acc0 = Vector256.MultiplyAddEstimate(Vector256.LoadUnsafe(ref row0, (uint)(x + 3)), Vector256.Create(this.weights[3]), acc0);
            acc1 = Vector256.MultiplyAddEstimate(Vector256.LoadUnsafe(ref row0, (uint)(x + 4)), Vector256.Create(this.weights[4]), acc1);
            acc2 = Vector256.MultiplyAddEstimate(Vector256.LoadUnsafe(ref row1, (uint)(x + 0)), Vector256.Create(this.weights[5]), acc2);
            acc0 = Vector256.MultiplyAddEstimate(Vector256.LoadUnsafe(ref row1, (uint)(x + 1)), Vector256.Create(this.weights[6]), acc0);
            acc1 = Vector256.MultiplyAddEstimate(Vector256.LoadUnsafe(ref row1, (uint)(x + 2)), Vector256.Create(this.weights[7]), acc1);
            acc2 = Vector256.MultiplyAddEstimate(Vector256.LoadUnsafe(ref row1, (uint)(x + 3)), Vector256.Create(this.weights[8]), acc2);
            acc0 = Vector256.MultiplyAddEstimate(Vector256.LoadUnsafe(ref row1, (uint)(x + 4)), Vector256.Create(this.weights[9]), acc0);
            acc1 = Vector256.MultiplyAddEstimate(Vector256.LoadUnsafe(ref row2, (uint)(x + 0)), Vector256.Create(this.weights[10]), acc1);
            acc2 = Vector256.MultiplyAddEstimate(Vector256.LoadUnsafe(ref row2, (uint)(x + 1)), Vector256.Create(this.weights[11]), acc2);
            acc0 = Vector256.MultiplyAddEstimate(Vector256.LoadUnsafe(ref row2, (uint)(x + 2)), Vector256.Create(this.weights[12]), acc0);
            acc1 = Vector256.MultiplyAddEstimate(Vector256.LoadUnsafe(ref row2, (uint)(x + 3)), Vector256.Create(this.weights[13]), acc1);
            acc2 = Vector256.MultiplyAddEstimate(Vector256.LoadUnsafe(ref row2, (uint)(x + 4)), Vector256.Create(this.weights[14]), acc2);
            acc0 = Vector256.MultiplyAddEstimate(Vector256.LoadUnsafe(ref row3, (uint)(x + 0)), Vector256.Create(this.weights[15]), acc0);
            acc1 = Vector256.MultiplyAddEstimate(Vector256.LoadUnsafe(ref row3, (uint)(x + 1)), Vector256.Create(this.weights[16]), acc1);
            acc2 = Vector256.MultiplyAddEstimate(Vector256.LoadUnsafe(ref row3, (uint)(x + 2)), Vector256.Create(this.weights[17]), acc2);
            acc0 = Vector256.MultiplyAddEstimate(Vector256.LoadUnsafe(ref row3, (uint)(x + 3)), Vector256.Create(this.weights[18]), acc0);
            acc1 = Vector256.MultiplyAddEstimate(Vector256.LoadUnsafe(ref row3, (uint)(x + 4)), Vector256.Create(this.weights[19]), acc1);
            acc2 = Vector256.MultiplyAddEstimate(Vector256.LoadUnsafe(ref row4, (uint)(x + 0)), Vector256.Create(this.weights[20]), acc2);
            acc0 = Vector256.MultiplyAddEstimate(Vector256.LoadUnsafe(ref row4, (uint)(x + 1)), Vector256.Create(this.weights[21]), acc0);
            acc1 = Vector256.MultiplyAddEstimate(Vector256.LoadUnsafe(ref row4, (uint)(x + 2)), Vector256.Create(this.weights[22]), acc1);
            acc2 = Vector256.MultiplyAddEstimate(Vector256.LoadUnsafe(ref row4, (uint)(x + 3)), Vector256.Create(this.weights[23]), acc2);
            acc0 = Vector256.MultiplyAddEstimate(Vector256.LoadUnsafe(ref row4, (uint)(x + 4)), Vector256.Create(this.weights[24]), acc0);

            // Native adds chains one and two first, then chain zero. Regrouping this sum changes cancellation and rounding.
            return (acc1 + acc2) + acc0;
        }

        /// <summary>
        /// Applies the native three-chain stencil to Vector128<float>.Count independent input centers.
        /// </summary>
        /// <param name="row0">The first input row, including horizontal halos.</param>
        /// <param name="row1">The second input row.</param>
