            acc2 = Vector128.MultiplyAddEstimate(Vector128.LoadUnsafe(ref row1, (uint)(x + 3)), Vector128.Create(this.weights[8]), acc2);
            acc0 = Vector128.MultiplyAddEstimate(Vector128.LoadUnsafe(ref row1, (uint)(x + 4)), Vector128.Create(this.weights[9]), acc0);
            acc1 = Vector128.MultiplyAddEstimate(Vector128.LoadUnsafe(ref row2, (uint)(x + 0)), Vector128.Create(this.weights[10]), acc1);
