            acc0 = Vector128.MultiplyAddEstimate(Vector128.LoadUnsafe(ref row2, (uint)(x + 2)), Vector128.Create(this.weights[12]), acc0);
            acc1 = Vector128.MultiplyAddEstimate(Vector128.LoadUnsafe(ref row2, (uint)(x + 3)), Vector128.Create(this.weights[13]), acc1);
            acc2 = Vector128.MultiplyAddEstimate(Vector128.LoadUnsafe(ref row2, (uint)(x + 4)), Vector128.Create(this.weights[14]), acc2);
