            acc1 = Vector128.MultiplyAddEstimate(Vector128.LoadUnsafe(ref row3, (uint)(x + 4)), Vector128.Create(this.weights[19]), acc1);
            acc2 = Vector128.MultiplyAddEstimate(Vector128.LoadUnsafe(ref row4, (uint)(x + 0)), Vector128.Create(this.weights[20]), acc2);
            acc0 = Vector128.MultiplyAddEstimate(Vector128.LoadUnsafe(ref row4, (uint)(x + 1)), Vector128.Create(this.weights[21]), acc0);
            acc1 = Vector128.MultiplyAddEstimate(Vector128.LoadUnsafe(ref row4, (uint)(x + 2)), Vector128.Create(this.weights[22]), acc1);
            acc2 = Vector128.MultiplyAddEstimate(Vector128.LoadUnsafe(ref row4, (uint)(x + 3)), Vector128.Create(this.weights[23]), acc2);
            acc0 = Vector128.MultiplyAddEstimate(Vector128.LoadUnsafe(ref row4, (uint)(x + 4)), Vector128.Create(this.weights[24]), acc0);

