        /// <summary>
        /// Applies the native three-chain stencil to one input center.
        /// </summary>
        /// <param name="row0">The first input row, including horizontal halos.</param>
        /// <param name="row1">The second input row.</param>
        /// <param name="row2">The middle input row.</param>
        /// <param name="row3">The fourth input row.</param>
        /// <param name="row4">The fifth input row.</param>
        /// <param name="x">The first center's offset before applying the two-sample left halo.</param>
        /// <returns>The unbounded weighted sum. The caller applies the neighborhood anti-ringing bounds.</returns>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public float InvokeScalar(ref float row0, ref float row1, ref float row2, ref float row3, ref float row4, int x)
        {
            float acc0 = Unsafe.Add(ref row0, x + 0) * this.weights[0];
            float acc1 = Unsafe.Add(ref row0, x + 1) * this.weights[1];
            float acc2 = Unsafe.Add(ref row0, x + 2) * this.weights[2];
            acc0 = float.MultiplyAddEstimate(Unsafe.Add(ref row0, x + 3), this.weights[3], acc0);
            acc1 = float.MultiplyAddEstimate(Unsafe.Add(ref row0, x + 4), this.weights[4], acc1);
            acc2 = float.MultiplyAddEstimate(Unsafe.Add(ref row1, x + 0), this.weights[5], acc2);
            acc0 = float.MultiplyAddEstimate(Unsafe.Add(ref row1, x + 1), this.weights[6], acc0);
            acc1 = float.MultiplyAddEstimate(Unsafe.Add(ref row1, x + 2), this.weights[7], acc1);
            acc2 = float.MultiplyAddEstimate(Unsafe.Add(ref row1, x + 3), this.weights[8], acc2);
            acc0 = float.MultiplyAddEstimate(Unsafe.Add(ref row1, x + 4), this.weights[9], acc0);
            acc1 = float.MultiplyAddEstimate(Unsafe.Add(ref row2, x + 0), this.weights[10], acc1);
            acc2 = float.MultiplyAddEstimate(Unsafe.Add(ref row2, x + 1), this.weights[11], acc2);
            acc0 = float.MultiplyAddEstimate(Unsafe.Add(ref row2, x + 2), this.weights[12], acc0);
            acc1 = float.MultiplyAddEstimate(Unsafe.Add(ref row2, x + 3), this.weights[13], acc1);
            acc2 = float.MultiplyAddEstimate(Unsafe.Add(ref row2, x + 4), this.weights[14], acc2);
            acc0 = float.MultiplyAddEstimate(Unsafe.Add(ref row3, x + 0), this.weights[15], acc0);
            acc1 = float.MultiplyAddEstimate(Unsafe.Add(ref row3, x + 1), this.weights[16], acc1);
            acc2 = float.MultiplyAddEstimate(Unsafe.Add(ref row3, x + 2), this.weights[17], acc2);
            acc0 = float.MultiplyAddEstimate(Unsafe.Add(ref row3, x + 3), this.weights[18], acc0);
            acc1 = float.MultiplyAddEstimate(Unsafe.Add(ref row3, x + 4), this.weights[19], acc1);
            acc2 = float.MultiplyAddEstimate(Unsafe.Add(ref row4, x + 0), this.weights[20], acc2);
            acc0 = float.MultiplyAddEstimate(Unsafe.Add(ref row4, x + 1), this.weights[21], acc0);
            acc1 = float.MultiplyAddEstimate(Unsafe.Add(ref row4, x + 2), this.weights[22], acc1);
            acc2 = float.MultiplyAddEstimate(Unsafe.Add(ref row4, x + 3), this.weights[23], acc2);
            acc0 = float.MultiplyAddEstimate(Unsafe.Add(ref row4, x + 4), this.weights[24], acc0);

            // Native adds chains one and two first, then chain zero. Regrouping this sum changes cancellation and rounding.
            return (acc1 + acc2) + acc0;
        }
    }
}
